package org.jlinalg.cli;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;

/** Capture, original execution, complete source-output audit and final admission. */
final class CrossmapWorkflow {
    private CrossmapWorkflow() { }
    static final String ACTION="Required action: read WARNINGS.md, FAILURE.json/BRIDGE-FAILURE.json when present, audit/original.stderr, process/process.stderr, OUTPUT-AUDIT.json and the complete OUTPUT-LEDGER.jsonl. Require COMPLETED.json and successful crossmap-tools --verify before downstream use. SKIP3 means the exact permitted runtime/platform/capability is unavailable: skip dependent conversion and complete separate authorized setup or supply the named prerequisite. FAIL2 means invalid/changed input, process, capacity, cancellation, output-consistency or finalization failure: no new complete result is admitted. Preserve all originals/attempts; correct the named cause and use NEW output paths. No source edition, assembly identity, unreported author setting, alternate mapper, phasing, imputation or GWAS model is inferred. Hashes establish integrity, not authenticity or biological accuracy. Cell Ranger remains excluded.";
    static Path start(Path requestFile,Path suppliedHome,Path report,Path output)throws IOException {
        var runtime=new CrossmapRuntime(suppliedHome,report);var request=CrossmapRequest.read(requestFile.toAbsolutePath().normalize(),true);runtime.source(request.edition());Path root=output.toAbsolutePath().normalize();
        if(root.getParent()==null||!root.getParent().toRealPath().equals(root.getParent())||root.startsWith(runtime.home())||runtime.home().startsWith(root)||root.startsWith(runtime.setupReport())||runtime.setupReport().startsWith(root))throw new IOException("Require a new canonical output outside the private runtime/setup report and their ancestors");
        Runnable cancelled=()->{if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("CrossMap conversion cancelled");};boolean fresh=false;String stage="CREATE_CAPTURED_REQUEST";
        try{
            Files.createDirectory(root);fresh=true;writeJson(root.resolve("INCOMPLETE.json"),Map.of("status","CROSSMAP_CONVERSION_NOT_COMMITTED","conversion_admitted",false));writeJson(root.resolve("request.json"),request.document());Files.writeString(root.resolve("WARNINGS.md"),"# INCOMPLETE — NO RESULT ADMITTED\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("outputs"));Files.createDirectory(root.resolve("support"));Files.createDirectory(root.resolve("runtime"));
            stage="CAPTURE_COMPLETE_ORIGINAL_INPUTS";var sources=new TreeMap<String,Object>();long total=0;
            for(var row:request.originals().entrySet()){
                Path original=Path.of(row.getValue());Pin identity=pin(original,request.inputBytes(),cancelled);total=Math.addExact(total,identity.bytes());require(total<=request.inputBytes(),"Complete original input bytes exceed capture.input_bytes");Path copy=root.resolve(row.getKey());Files.copy(original,copy);require(pin(copy,request.inputBytes(),cancelled).equals(identity)&&pin(original,request.inputBytes(),cancelled).equals(identity),"Original input changed during complete capture: "+row.getKey());sources.put(row.getKey(),Map.of("original",row.getValue(),"pin",identity));
            }
            writeJson(root.resolve("source-inputs.json"),Map.of("files",sources,"complete_original_bytes",total,"source_bytes_unchanged",true));
            if(request.fasta()!=null)try(var input=Files.newInputStream(root.resolve(request.fastaMember()))){if(input.read()==31&&input.read()==139)throw new CrossmapRuntime.Unavailable("This reference contract requires an explicit uncompressed FASTA; retain the original and provide a permitted separate uncompressed reference before conversion");}
            for(String name:List.of("source-lock.json","analysis.py"))Files.write(root.resolve("support").resolve(name),CrossmapRuntime.resource(name),StandardOpenOption.CREATE_NEW);
            copy(runtime.home().resolve("runtime.json"),root.resolve("runtime/marker.json"));copy(runtime.setupReport().resolve("COMPLETED.json"),root.resolve("runtime/setup-completed.json"));copy(runtime.setupReport().resolve("health/COMPLETED.json"),root.resolve("runtime/health-completed.json"));writeJson(root.resolve("runtime/provenance.json"),runtime.provenance());runtime.verify();
            stage="ORIGINAL_CONVERSION_AND_COMPLETE_RECORD_AUDIT";var command=List.of(runtime.python().toString(),"-I","-B",root.resolve("support/analysis.py").toString(),"--root",root.toString(),"--home",runtime.home().toString());var environment=Map.of("PATH","/usr/bin:/bin","LANG","C.UTF-8","LC_ALL","C.UTF-8","PYTHONDONTWRITEBYTECODE","1","OPENBLAS_NUM_THREADS","1","OMP_NUM_THREADS","1");
            try{NextflowProcess.executeSession(command,environment,root.resolve("process"),root,root,request.process(),runtime::verify,cancelled);}catch(IOException failure){throw new IOException("Original CrossMap conversion or complete output audit failed. Inspect retained original.stderr, process stderr and bridge failure; no complete result is admitted",failure);}
            stage="NATIVE_COMPLETE_OUTPUT_VERIFICATION";CrossmapBundle.audit(root,request,cancelled);runtime.verify();checkOriginals(request,sources,cancelled);Files.writeString(root.resolve("WARNINGS.md"),warnings(root,request),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING);
            stage="FINALIZE_CAPTURED_RESULT";var files=CrossmapBundle.files(root,request,cancelled);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile","crossmap-original-source-conversion-v1","status","COMPLETE_ORIGINAL_CROSSMAP_CAPTURED_CONTRACT","files",files,"producer",CrossmapBundle.producer(),"conversion_admitted",true,"whole_paper_reproduced",false));writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_ORIGINAL_CROSSMAP_CONVERSION","manifest",pin(root.resolve("manifest.json"),16777216,cancelled),"conversion_admitted",true));
            CrossmapBundle.verify(root,true,cancelled);runtime.verify();checkOriginals(request,sources,cancelled);cancelled.run();Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error failure){if(fresh)failure(root,stage,failure);throw failure;}
    }
    private static void copy(Path source,Path target)throws IOException {var before=pin(source,4194304,()->{});Files.copy(source,target);require(before.equals(pin(target,4194304,()->{}))&&before.equals(pin(source,4194304,()->{})),"Runtime/setup evidence changed during capture");}
    private static void checkOriginals(CrossmapRequest.Spec request,Map<String,Object> sources,Runnable check)throws IOException {
        for(var row:request.originals().entrySet())require(pin(Path.of(row.getValue()),request.inputBytes(),check).equals(object(sources.get(row.getKey())).get("pin")),"Original input changed before final admission: "+row.getKey());
    }
    static String warnings(Path root,CrossmapRequest.Spec request)throws IOException {
        var report=object(json(root.resolve("OUTPUT-AUDIT.json"),16777216));var counts=object(report.get("counts"));
        return "# CROSSMAP WARNINGS AND REQUIRED ACTION\n\nOriginal CrossMap "+request.edition()+"; selected format "+request.format()+".\n\nComplete source outcomes: "+NextflowJson.json(counts)+"\n\nOriginal rejections, source partial spans, split/multiple output blocks, signal discards and overlapping-target summation are retained. A rejected or unmapped input is not a biological negative finding. Review every ledger disposition and original diagnostic before downstream use. A source BED20 conversion can omit extra metadata columns; all original rows remain captured.\n\nVCF reference/ALT, reverse-complement, END-field and unchanged genotype-column behavior belongs to the selected original edition. The0.5.2 indel ALT behavior differs from0.6.3. Source-generated path/basename/date metadata refer to the captured execution; the original paths and exact input bytes remain recorded separately. Target FASTA indexes generated by the original source remain captured. Assembly labels "+request.sourceBuild()+" -> "+request.targetBuild()+" are declarations, not genome-identity verification.\n\nThe qualified interpreter is CPython3.12.3; P072's reported Python3.7 environment is not reproduced. Original SyntaxWarning and other source messages remain in audit/original.stderr and process/process.stderr. Both versions reject the tested reverse multiblock BED12;0.6.3 can fail without VCF contig metadata. Empty/unmappable BigWig input cases can fail in original iteration/merge routines. No automatic scientific repair is made.\n\nPortable verification requires the exact producing executable JAR and checks complete captured bytes, record witnesses, source-output consistency and native binary/reference readback. It does not execute the original runtime, refit a model, reproduce author-unreported settings or certify biological accuracy. Keep the producer and private source/runtime evidence. Declared process/capture bounds do not guarantee sufficient JVM heap.\n\n"+ACTION+"\n";
    }
    static void failure(Path root,String stage,Throwable failure){
        try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("INCOMPLETE.json")))writeJson(root.resolve("INCOMPLETE.json"),Map.of("status","FAILED_CROSSMAP_CONVERSION_NOT_COMMITTED","conversion_admitted",false));writeJson(root.resolve("FAILURE.json"),Map.of("status",failure instanceof CrossmapRuntime.Unavailable?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT","stage",stage,"error",failure.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"# NO COMPLETE CROSSMAP RESULT ADMITTED\n\n"+stage+": "+failure+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}catch(IOException diagnostic){failure.addSuppressed(diagnostic);}
    }
    private static void require(boolean value,String message)throws IOException {if(!value)throw new IOException(message);}
}
